permission_denials.command:
cat lab/logs/app.log | python3 -I -c "
import sys, json
for line in sys.stdin:
    try:
        d = json.loads(line)
    except Exception:
        continue
    print(d.get('ts'), d.get('event'), d.get('path'), d.get('status'), d.get('duration_ms'), d.get('request_id'))
" 2>&1 || grep -o '"ts": "[^"]*".*"event": "[^"]*"' lab/logs/app.log
